import json
from typing import Dict, List

class HierarchicalSupplyChainReconciler:
    def __init__(self, hierarchy_structure: Dict[str, List[str]]):
        self.hierarchy = hierarchy_structure  # Parent -> Children mapping

    def evaluate_coherence(self, forecasts: Dict[str, float]) -> Dict[str, float]:
        discrepancies = {}
        for parent, children in self.hierarchy.items():
            sum_children = sum(forecasts[c] for c in children)
            diff = round(forecasts[parent] - sum_children, 2)
            discrepancies[f'{parent}_vs_children_sum'] = diff
        return discrepancies

    def bottom_up_reconcile(self, base_forecasts: Dict[str, float]) -> Dict[str, float]:
        reconciled = dict(base_forecasts)
        # Reconcile intermediate hubs from DCs
        reconciled['Region_East'] = reconciled['DC_NewYork'] + reconciled['DC_Boston']
        reconciled['Region_West'] = reconciled['DC_Seattle'] + reconciled['DC_SanFrancisco']
        # Reconcile Enterprise Total from Hubs
        reconciled['Enterprise_Total'] = reconciled['Region_East'] + reconciled['Region_West']
        return reconciled

    def top_down_proportion_reconcile(self, base_forecasts: Dict[str, float], top_target: float) -> Dict[str, float]:
        # Historical sales proportions
        proportions = {
            'DC_NewYork': 0.35, 'DC_Boston': 0.20,
            'DC_Seattle': 0.25, 'DC_SanFrancisco': 0.20
        }
        reconciled = {'Enterprise_Total': top_target}
        reconciled['Region_East'] = round(top_target * (proportions['DC_NewYork'] + proportions['DC_Boston']), 1)
        reconciled['Region_West'] = round(top_target * (proportions['DC_Seattle'] + proportions['DC_SanFrancisco']), 1)
        for dc, p in proportions.items():
            reconciled[dc] = round(top_target * p, 1)
        return reconciled

structure = {
    'Enterprise_Total': ['Region_East', 'Region_West'],
    'Region_East': ['DC_NewYork', 'DC_Boston'],
    'Region_West': ['DC_Seattle', 'DC_SanFrancisco']
}

incoherent_raw = {
    'Enterprise_Total': 10000.0,  # Top-down corporate target
    'Region_East': 5800.0, 'Region_West': 4800.0, # Regional managers sum = 10,600
    'DC_NewYork': 3400.0, 'DC_Boston': 2100.0,    # Sum = 5,500 (!= 5,800)
    'DC_Seattle': 2600.0, 'DC_SanFrancisco': 2400.0 # Sum = 5,000 (!= 4,800)
}

reconciler = HierarchicalSupplyChainReconciler(structure)
pre_audit = reconciler.evaluate_coherence(incoherent_raw)
bottom_up = reconciler.bottom_up_reconcile(incoherent_raw)
post_audit = reconciler.evaluate_coherence(bottom_up)

report = {
    'pre_reconciliation_discrepancies': pre_audit,
    'bottom_up_reconciled_forecasts': bottom_up,
    'post_reconciliation_discrepancies': post_audit,
    'hierarchical_coherence_verified': all(v == 0.0 for v in post_audit.values())
}
print(json.dumps(report, indent=2))
